# Block OPTIONS method on root path, often used for reconnaissance
# Review if you have legitimate CORS preflight requests to /.
"OPTIONS /" 1;

# Block PUT/DELETE on root path (should not be allowed for static assets)
"PUT /" 1;
"DELETE /" 1;
